const ICON_OVERRIDES = {
  brandOpenRouter: {
    viewBox: '0 0 512 512',
    attrs: 'fill="currentColor" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"',
  },
};

function svg(name, extra = '') {
  const entry = ICONS[name];
  if (!entry) return '';
  const override = ICON_OVERRIDES[name];
  if (override) {
    return `<svg class="icon" viewBox="${override.viewBox}" ${override.attrs} ${extra}>${entry}</svg>`;
  }
  return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" ${extra}>${entry}</svg>`;
}

function mountIcons(root = document) {
  root.querySelectorAll('[data-icon]').forEach((el) => {
    const name = el.getAttribute('data-icon');
    el.innerHTML = svg(name);
  });
}

// ── Settings tabs ────────────────────────────────────────────
function wireTabs() {
  const tabs = document.querySelectorAll('[data-tab]');
  const panels = document.querySelectorAll('[data-panel]');
  tabs.forEach((tab) => {
    tab.addEventListener('click', () => {
      const target = tab.getAttribute('data-tab');
      tabs.forEach((t) => t.setAttribute('data-active', String(t === tab)));
      panels.forEach((p) =>
        p.setAttribute('data-active', String(p.getAttribute('data-panel') === target)),
      );
      // Update title strip
      const titleEl = document.querySelector('[data-stage-title]');
      if (titleEl) titleEl.textContent = tab.textContent.trim();
      window.scrollTo({ top: 0, behavior: 'instant' });
    });
  });
}

// ── Single-select radio group (preset cards, segmented control)
function wireRadioGroups(root = document) {
  root.querySelectorAll('[data-radio-group]').forEach((group) => {
    group.querySelectorAll('[data-radio]').forEach((el) => {
      el.addEventListener('click', () => {
        group.querySelectorAll('[data-radio]').forEach((c) =>
          c.setAttribute('data-selected', 'false'),
        );
        el.setAttribute('data-selected', 'true');
      });
    });
  });
}

// ── Toggle ───────────────────────────────────────────────────
function wireToggles(root = document) {
  root.querySelectorAll('[data-toggle]').forEach((el) => {
    el.addEventListener('click', () => {
      const cur = el.getAttribute('data-on') === 'true';
      el.setAttribute('data-on', String(!cur));
    });
  });
}

// ── Multi-select pill (document types) ───────────────────────
function wirePills(root = document) {
  root.querySelectorAll('[data-pill]').forEach((el) => {
    el.addEventListener('click', () => {
      const cur = el.getAttribute('data-selected') === 'true';
      el.setAttribute('data-selected', String(!cur));
    });
  });
}

// ── Modal open/close ─────────────────────────────────────────
function openModal(id, context = {}) {
  const overlay = document.querySelector(`[data-modal="${id}"]`);
  if (!overlay) {
    openModal('stub', { title: id, body: 'Demo modal not yet implemented for this row.' });
    return;
  }
  // Close any other open modal first (so chained openers don't stack).
  document.querySelectorAll('[data-modal]').forEach((m) => {
    if (m !== overlay) m.setAttribute('data-open', 'false');
  });
  overlay.setAttribute('data-open', 'true');
  // Generic title/body prefill: any modal with [data-stub-title]/[data-stub-body]
  // can be customised via data-context-title / data-context-body on the trigger.
  if (context.title) {
    const titleEl = overlay.querySelector('[data-stub-title]');
    if (titleEl) titleEl.textContent = context.title;
  }
  if (context.body) {
    const bodyEl = overlay.querySelector('[data-stub-body]');
    if (bodyEl) bodyEl.textContent = context.body;
  }
  // For Provider edit modal: pre-fill the provider name in header
  if (id === 'providerEdit' && context.name) {
    const titleEl = overlay.querySelector('[data-provider-title]');
    if (titleEl) titleEl.textContent = `Edit ${context.name}`;
  }
  // For Change-model modal: set the capability label
  if (id === 'chooseModel' && context.capability) {
    const titleEl = overlay.querySelector('[data-capability-title]');
    if (titleEl) titleEl.textContent = `Choose ${context.capability} model`;
  }
  document.body.style.overflow = 'hidden';
}

function closeAllModals() {
  document.querySelectorAll('[data-modal]').forEach((m) => m.setAttribute('data-open', 'false'));
  document.body.style.overflow = '';
}

function wireModalTriggers() {
  document.addEventListener('click', (e) => {
    // Trigger: [data-open-modal="id"][data-context-name="..."] etc.
    const opener = e.target.closest('[data-open-modal]');
    if (opener) {
      e.preventDefault();
      e.stopPropagation();
      const id = opener.getAttribute('data-open-modal');
      const context = {
        name: opener.getAttribute('data-context-name') || '',
        capability: opener.getAttribute('data-context-capability') || '',
        title: opener.getAttribute('data-context-title') || '',
        body: opener.getAttribute('data-context-body') || '',
      };
      openModal(id, context);
      return;
    }
    // Trigger: [data-close-modal]
    const closer = e.target.closest('[data-close-modal]');
    if (closer) {
      e.preventDefault();
      closeAllModals();
      return;
    }
    // Click on the overlay backdrop (but not on the shell) closes
    if (e.target.classList && e.target.classList.contains('modal-overlay')) {
      closeAllModals();
    }
  });

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeAllModals();
  });
}

// ── Hash routing: open #aiSetup / #knowledgeIndex / #tools / #advanced ──
function applyHashTab() {
  const hash = (location.hash || '').replace(/^#/, '');
  if (!hash) return;
  const tab = document.querySelector(`[data-tab="${hash}"]`);
  if (tab) tab.click();
}

function applyOpenParam() {
  const params = new URLSearchParams(location.search);
  const id = params.get('open');
  if (id) openModal(id);
}

document.addEventListener('DOMContentLoaded', () => {
  mountIcons();
  wireTabs();
  wireRadioGroups();
  wireToggles();
  wirePills();
  wireModalTriggers();
  applyHashTab();
  applyOpenParam();
});

window.addEventListener('hashchange', applyHashTab);
